arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) printf '%s\n' "x-access-token" ;;
  *Password*) printf '%s\n' "$GITHUB_TOKEN" ;;
  *) printf '%s\n' "" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
cd /tmp/phoebe-conv && GIT_ASKPASS=/tmp/git-askpass.sh GIT_TERMINAL_PROMPT=0 git push --quiet origin HEAD:refs/heads/friend/phoebe && echo PUSH_OK && git ls-remote origin refs/heads/friend/phoebe
